/**
 * Root-level MCP env declaration shared by dev, build, and typecheck.
 *
 * Combines CSS module typing and a live type-only edge to the server entry so
 * exported `ToolRef`s update in TypeScript without rerunning the CLI.
 */

import { readFile, writeFile } from "node:fs/promises";
import { extname, join, relative, sep } from "node:path";

/** Filename of the project-owned MCP env declaration. */
export const MCP_ENV_DECLARATION_NAME = "mcp-env.d.ts";

/** Header used to identify declarations that mcp-use may safely refresh. */
export const MCP_ENV_DECLARATION_HEADER =
  "// Generated by mcp-use. Do not edit.";

const LEGACY_MANAGED_HEADERS = [
  "// mcp-use generated env declaration",
  "// mcp-use auto-generated typing",
] as const;

/** Result of reconciling the project's MCP environment declaration. */
export type McpEnvDeclarationStatus =
  | "created"
  | "updated"
  | "unchanged"
  | "user-owned";

function declarationImportPath(cwd: string, entry: string): string {
  let importPath = relative(cwd, entry).split(sep).join("/");
  const extension = extname(importPath);
  const runtimeExtension =
    extension === ".mts"
      ? ".mjs"
      : extension === ".cts"
        ? ".cjs"
        : extension === ".ts" || extension === ".tsx"
          ? ".js"
          : extension;

  if (extension !== runtimeExtension) {
    importPath = `${importPath.slice(0, -extension.length)}${runtimeExtension}`;
  }
  return importPath.startsWith(".") ? importPath : `./${importPath}`;
}

/** Build the stable declaration contents for a discovered server entry. */
export function renderMcpEnvDeclaration(cwd: string, entry: string): string {
  const importPath = declarationImportPath(cwd, entry);
  return [
    MCP_ENV_DECLARATION_HEADER,
    'declare module "*.css";',
    "",
    'declare module "mcp-use/react" {',
    "  interface Register {",
    `    tools: typeof import(${JSON.stringify(importPath)});`,
    "  }",
    "}",
    "",
    "export {};",
    "",
  ].join("\n");
}

/**
 * Reconcile the root `mcp-env.d.ts` with the discovered server entry.
 *
 * Files generated by current or earlier mcp-use versions are refreshed. A file
 * without a recognized generated header is treated as user-owned and is never
 * replaced. Exclusive creation keeps concurrent command startup safe.
 *
 * @returns How the declaration changed, or why it was left alone.
 */
export async function syncMcpEnvDeclaration(
  cwd: string,
  entry: string
): Promise<McpEnvDeclarationStatus> {
  const declarationPath = join(cwd, MCP_ENV_DECLARATION_NAME);
  const next = renderMcpEnvDeclaration(cwd, entry);

  try {
    const current = await readFile(declarationPath, "utf8");
    if (current === next) return "unchanged";
    if (!isManagedDeclaration(current)) return "user-owned";

    await writeFile(declarationPath, next, "utf8");
    return "updated";
  } catch (error) {
    if (!hasErrorCode(error, "ENOENT")) throw error;
  }

  try {
    await writeFile(declarationPath, next, { encoding: "utf8", flag: "wx" });
    return "created";
  } catch (error) {
    if (!hasErrorCode(error, "EEXIST")) throw error;
    return syncMcpEnvDeclaration(cwd, entry);
  }
}

/** Whether a declaration carries a current or legacy mcp-use marker. */
function isManagedDeclaration(contents: string): boolean {
  return [MCP_ENV_DECLARATION_HEADER, ...LEGACY_MANAGED_HEADERS].some(
    (header) => contents.startsWith(header)
  );
}

/** Narrow an unknown filesystem failure to a Node error code. */
function hasErrorCode(error: unknown, code: string): boolean {
  return (
    error !== null &&
    typeof error === "object" &&
    "code" in error &&
    error.code === code
  );
}
